  [1307227] = { "Costruisce un fuoco da campo semplice che permette di cucinare e di collocare fino a $N1 elementi da campeggio aggiuntivi. I giocatori che restano seduti o creano oggetti nelle vicinanze per $D1 ottengono i benefici degli altri elementi da campeggio.", nil, 0x7f185d8f, nil, "um" },
